#include "keypad_manager.h"
void KeypadManager::begin(ConfigStore& config, AlarmCore& core){config_=&config;core_=&core;for(uint8_t k=0;k<config_->keypadCount();++k)for(uint8_t i=0;i<8;++i){core_->setSensorInUse(logicalSlot(k,i),config_->keypad(k).authorized);core_->setSensor(logicalSlot(k,i),false,true);}}
bool KeypadManager::authorized(const String& mac)const{if(!config_)return false;int8_t i=config_->findKeypad(mac);return i>=0&&config_->keypad(i).authorized;}
int8_t KeypadManager::enrollIdentity(const String& mac,const String& ip,const String& name,const String& firmware){if(!config_||!mac.length())return -1;KeypadRecord r;int8_t old=config_->findKeypad(mac);if(old>=0)r=config_->keypad(old);r.authorized=true;r.mac=mac;r.ip=ip;r.name=name;r.firmware=firmware;int8_t idx=config_->saveKeypad(r);if(idx>=0&&core_)for(uint8_t i=0;i<8;++i)core_->setSensorInUse(logicalSlot(idx,i),true);return idx;}
bool KeypadManager::receiveHeartbeat(const String& mac,const String& ip,uint32_t now){if(!authorized(mac))return false;int8_t i=config_->findKeypad(mac);if(i<0)return false;KeypadRecord r=config_->keypad(i);r.ip=ip;config_->saveKeypad(r);runtime_[i].online=true;runtime_[i].snapshot_pending=true;runtime_[i].last_heartbeat=now;return true;}
bool KeypadManager::receiveSnapshot(const String& mac,const bool open[8],uint32_t now){if(!authorized(mac))return false;int8_t k=config_->findKeypad(mac);if(k<0)return false;for(uint8_t i=0;i<8;++i)core_->setSensor(logicalSlot(k,i),open[i],false);runtime_[k].snapshot_pending=false;runtime_[k].online=true;runtime_[k].last_heartbeat=now;return true;}
void KeypadManager::setFault(uint8_t k,bool fault){for(uint8_t i=0;i<8;++i)core_->setSensor(logicalSlot(k,i),false,fault);}
void KeypadManager::tick(uint32_t now){if(!config_||!core_)return;for(uint8_t k=0;k<config_->keypadCount();++k){if(!config_->keypad(k).authorized)continue;if(runtime_[k].online&&static_cast<uint32_t>(now-runtime_[k].last_heartbeat)>=OFFLINE_AFTER_MS){runtime_[k].online=false;runtime_[k].snapshot_pending=true;setFault(k,true);} }}
